    /// Safe wrapper that guards against passing null to DropDownControl,
    /// which throws ArgumentNullException in .NET 9.
    /// </summary>
    public static void SafeDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

